#undef NDEBUG
#include "assoc.h"
#include "gate_events.h"
#include "nrf_802154_types.h"
#include <assert.h>
#include <stdio.h>
int main(void) {
 const unsigned char b137[]={0x00,0x80,0x19,0x9b,0xfa,0x00,0x00,0xff,0xcf,0x00,0x00,0x00,0x22,0x84,0xe5,0x48,0xa1,0x36,0x00,0x4b,0x12,0x00,0xff,0xff,0xff,0x00}, b99[]={0x00,0x80,0x18,0x9b,0xfa,0x00,0x00,0xff,0x4f,0x00,0x00,0x00,0x22,0x84,0xe5,0x48,0xa1,0x36,0x00,0x4b,0x12,0x00,0xff,0xff,0xff,0x00};
 assoc_beacon_t b;assoc_t s;assoc_init(&s);assoc_filter_bind(&s);
 assert(assoc_beacon_parse(b137,sizeof b137,&b));
 assert(b.pan==0xfa9b && b.source_short==0 && b.dsn==25);
 assert(b.permit && b.coordinator && b.router_capacity && b.end_capacity);
 assert(assoc_beacon_parse(b99,sizeof b99,&b) && !b.permit);
 unsigned char raw[128]={0};raw[0]=sizeof b137+2;
 for(unsigned i=0;i<sizeof b137;i++)raw[i+1]=b137[i];
 unsigned char received=3;int result=assoc_filter_part(raw,&received);
 assert(result==NRF_802154_RX_ERROR_INVALID_DEST_ADDR);
 /* Actual Nordic core keeps this error in promiscuous RX; source audited separately. */
 assert(assoc_beacon_parse(raw+1,raw[0]-2,&b));
 puts("HISTORICAL_FRAME137_RUNTIME_PARSER PASS; frame99 permit0 PASS; idle filter INVALID_DEST_ADDR expected for ACK-only allowlist; promiscuous RX source audited");return 0;
}
